-- Índice composto: coluna de igualdade primeiro, depois a de intervalo
CREATE INDEX idx_pedidos_status_data ON pedidos (status, criado_em);

-- Índice de expressão para busca case-insensitive
CREATE INDEX idx_usuarios_email_lower ON usuarios (lower(email));

-- Parcial: só pedidos ainda não finalizados
CREATE INDEX idx_pedidos_pendentes ON pedidos (criado_em) WHERE status = 'PENDENTE';

-- Cobertura: evita ir à tabela para buscar o total
CREATE INDEX idx_pedidos_cliente ON pedidos (cliente_id) INCLUDE (total);

-- GIN para consultas em JSONB
CREATE INDEX idx_produtos_atributos ON produtos USING GIN (atributos);

