-- Particionamento por intervalo de data (PostgreSQL)
CREATE TABLE eventos (
  id BIGSERIAL,
  criado_em TIMESTAMP NOT NULL,
  payload JSONB
) PARTITION BY RANGE (criado_em);

CREATE TABLE eventos_2024_05 PARTITION OF eventos
  FOR VALUES FROM ('2024-05-01') TO ('2024-06-01');

